#!/usr/bin/env python3
"""Infer two named settlement footprints from literal streets and building rows."""
from pathlib import Path
import json
from shapely.geometry import Polygon,mapping,Point
H=Path(__file__).resolve().parent
URL='https://www.ozd.hu/adat/Ozd_varos_honlapja_fajlok/Varoshaza/Tajekoztatok_es_felhivasok/Kozerdeku_adatok_es_informaciok/gazdasagi_informaciok/strategia_terv/2715-ozd-its-helyzetfeltaras-.pdf'
rows=[{'name':'Bánszállás','point':[20.353867,48.2459291],'pages':[250,277],'roadIds':[76733941,272466254,272466255,272466257,272466264,469785004,543573079,543573080,543573081],'points':[[20.3507,48.2484],[20.3521,48.2490],[20.3532,48.2488],[20.3541,48.2490],[20.3548,48.2486],[20.3556,48.2486],[20.3574,48.2473],[20.3576,48.2469],[20.3565,48.2461],[20.3558,48.2453],[20.3550,48.2452],[20.3541,48.2455],[20.3535,48.2456],[20.3534,48.2461],[20.3520,48.2473],[20.3507,48.2480]],'note':'Populated Bánszállás telep core inferred from the diagonal grid of literal Bánszállás telep streets and actual building rows. The 2015 study identifies the locality and shows the same road topology at page277; its red statistical-cell fill is not asserted to equal the entire suburb. Outer garden margins hand-estimated; remote southern access road and detached industrial shed excluded.'},{'name':'Center','point':[20.3640525,48.2547244],'pages':[250,283],'roadIds':[272466250,272466263,380373549,547781520,355359053,355359065,1022729988],'points':[[20.3604,48.2551],[20.3613,48.2564],[20.3613,48.2571],[20.3620,48.2577],[20.3619,48.2585],[20.3625,48.2593],[20.3633,48.2593],[20.3639,48.2585],[20.3645,48.2575],[20.3649,48.2570],[20.3652,48.2561],[20.3667,48.2556],[20.3669,48.2551],[20.3661,48.2547],[20.3649,48.2547],[20.3644,48.2542],[20.3637,48.2541],[20.3632,48.2534],[20.3627,48.2536],[20.3627,48.2541],[20.3615,48.2544]],'note':'Center settlement footprint follows the actual Center út, Sajó utca and Tóth Ede utca housing rows and connecting junctions. Municipal study p250 explicitly identifies Center; p283 documents the Sajó utca–Center út context. The small red segregation area is not relabelled as the whole village. Peripheral gardens and north/south separators are hand-estimated.'}]
features=[]
for r in rows:
 g=Polygon(r['points']);assert g.is_valid and g.covers(Point(r['point']))
 features.append({'type':'Feature','properties':{'name':r['name'],'municipality':'Ózd','method':'named_settlement_actual_road_building_footprint_estimate','estimated':True,'confidence':'low','qualityScore':15,'sourceUrl':URL,'sourceYear':2015,'sourcePages':r['pages'],'sourceRoadFile':'ozd-source-roads.geojson.gz','sourceBuildingFile':'ozd-source-areas.geojson.gz','sourceRoadIds':r['roadIds'],'contextPreview':'ozd-outer-road-context.png','approximationNote':r['note']+' Low-confidence neighbourhood estimate, not an official or complete cadastral boundary. No point-radius construction.','osmSnapshot':'2026-11-12T21:23:05Z','license':'ODbL-1.0','attribution':'© OpenStreetMap contributors','radiusFallback':False},'geometry':mapping(g)})
(H/'ozd-outer-traces.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(H/'ozd-outer-features.geojson').write_text(json.dumps({'type':'FeatureCollection','features':features},ensure_ascii=False,separators=(',',':'))+'\n')
print(len(features))
